<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import CloudDirectoryPicker from './CloudDirectoryPicker.vue';
import UploadDirectorySelection from './UploadDirectorySelection.vue';
import UploadDirectoryResults from './UploadDirectoryResults.vue';
import UploadConcurrencySettings from './UploadConcurrencySettings.vue';
import UploadStorageStatus from './UploadStorageStatus.vue';
import {validUploadDirectories,directorySummary,type UploadDirectory,type DirectorySummary} from './upload-directory-types';
import type {DirectorySelection} from './upload-directory-selection';
import UploadBatchStop from './UploadBatchStop.vue';
import type {CloudActionResult} from './cloud-files-types';
import WorkspaceSidebar from './WorkspaceSidebar.vue';
import UploadRecoveryHistory from './UploadRecoveryHistory.vue';
import UploadSessionDetails from './UploadSessionDetails.vue';
import UploadTransferStatistics from './UploadTransferStatistics.vue';
import {formatBytes} from './format-bytes';
import {validCloudDirectory} from './cloud-files-route';
import {uploadSummary,uploadItemProgress,validUploadItem,uploadNames as names,type UploadItem as Item} from './upload-progress';
type Batch={directories?:UploadDirectory[];directory_summary?:DirectorySummary;id:string;target:string;created_at_utc:string;items?:Item[];total?:number;completed?:number;failed?:number;unknown?:number};
const target=ref(new URLSearchParams(location.search).get('directory')||'/'),batches=ref<Batch[]>([]),batch=ref<Batch|null>(null),files=ref<File[]>([]),error=ref(''),busy=ref(false),auth=ref(false),transferred=ref(''),filter=ref(''),page=ref(0),ack=ref(false);
// Browser review found an empty table indistinguishable from a pending or failed history read.
const historyLoaded=ref(false),historyLoading=ref(false),historyFresh=ref(false),historyError=ref(''),historyObserved=ref('');
const completeDirectories=ref<string[]>([]),emptyDirectories=ref(0),enumerationBusy=ref(false);
let selectedPaths=new Map<File,string>();
function enumerating(value:boolean){enumerationBusy.value=value;if(value)ack.value=false;}
function completeSelection(selection:DirectorySelection){if(!active||auth.value||busy.value||batch.value)return;files.value=selection.files.map(entry=>entry.file);selectedPaths=new Map(selection.files.map(entry=>[entry.file,entry.path]));completeDirectories.value=selection.directories;emptyDirectories.value=selection.emptyDirectories;ack.value=false;error.value='';}
const selectedBytes=computed(()=>files.value.reduce((total,file)=>total+BigInt(file.size),0n).toString());
const directoryCounts=computed(()=>directorySummary(batch.value?.directories||[]));
const sessionItem=ref(''),stopReview=ref(false);
function reviewStop(){if(!active||!batch.value||busy.value||controlBusy.value||auth.value||enumerationBusy.value||pickerOpen.value||pickerBusy.value)return;stopReview.value=true;}
watch(()=>batch.value?.id,()=>{sessionItem.value='';stopReview.value=false;});
function showSession(item:string){sessionItem.value=sessionItem.value===item?'':item;queueMicrotask(()=>document.querySelector<HTMLElement>('[data-testid=upload-session-details]')?.scrollIntoView?.({block:'nearest'}));}
const controlBusy=ref(''),controlFeedback=ref(''),controlRevision=ref(0);
let controlGeneration=0,controlController:AbortController|undefined;
const pickerOpen=ref(false),pickerBusy=ref(false),pickerConfirmed=ref(false),pickerUnknown=ref(false),directoryResult=ref<CloudActionResult|null>(null),pickerBusyLabel=ref('');
watch(target,()=>ack.value=false);
function togglePicker(){if(!active||enumerationBusy.value||busy.value||auth.value||batch.value||pickerBusy.value||pickerUnknown.value)return;ack.value=false;pickerOpen.value=!pickerOpen.value;}
function closePicker(){if(pickerBusy.value)return;pickerOpen.value=false;queueMicrotask(()=>document.querySelector<HTMLElement>('[data-testid=upload-pick-directory]')?.focus());}
function escapePicker(event:KeyboardEvent){if(pickerOpen.value){event.preventDefault();event.stopPropagation();closePicker();}}
function picked(path:string){if(!active||pickerBusy.value||pickerUnknown.value||batch.value)return;target.value=path;ack.value=false;closePicker();}
function directoryBusy(value:boolean,label='',confirmed=false){pickerBusy.value=value;pickerBusyLabel.value=label;pickerConfirmed.value=value&&confirmed;if(value)ack.value=false;}
function directoryConfirmed(value:CloudActionResult){if(active)directoryResult.value=value;}
function directoryUnknown(value:CloudActionResult){directoryResult.value=value;pickerUnknown.value=true;ack.value=false;pickerBusy.value=false;pickerConfirmed.value=false;pickerOpen.value=false;queueMicrotask(()=>document.querySelector<HTMLElement>('[data-testid=upload-directory-result] a')?.focus());}
const priority:Record<string,number>={uploading:0,submitting:0,finalizing:0,hashing:0,unknown:1,failed:1,queued:2,receiving:3,paused:2,confirmed:4,cancelled:5};
const visible=computed(()=>{const all=batch.value?.items||[];return all.filter(i=>!filter.value||i.state===filter.value).sort((a,b)=>priority[a.state]-priority[b.state]||a.path.localeCompare(b.path)).slice(page.value*100,(page.value+1)*100)}),matched=computed(()=>(batch.value?.items||[]).filter(i=>!filter.value||i.state===filter.value).length);
// Polled status changes can shrink a filtered result beneath the current page.
watch(matched,count=>{page.value=Math.min(page.value,Math.max(0,Math.ceil(count/100)-1));});
const summary=computed(()=>uploadSummary(batch.value?.items||[]));
const stateCounts=computed(()=>{const counts=Object.fromEntries(Object.keys(names).map(state=>[state,0]));for(const item of batch.value?.items||[])counts[item.state]++;return counts;});
const completed=computed(()=>(batch.value?.items||[]).filter(i=>i.state==='confirmed').length);
let active=true,generation=0,lifecycle=0,controller:AbortController|undefined,xhr:XMLHttpRequest|undefined,timer:ReturnType<typeof setTimeout>|undefined;
function remoteLocation(item:Item){const path=item.actual_path;if(item.state!=='confirmed'||path==='/'||!validCloudDirectory(path))return '';return '/cloud/files?dir='+encodeURIComponent(path.slice(0,path.lastIndexOf('/'))||'/');}
function filename(file:File){return selectedPaths.get(file)||file.webkitRelativePath||file.name;}
function choose(event:Event){if(enumerationBusy.value||busy.value||auth.value||enumerationBusy.value||pickerOpen.value||pickerBusy.value||pickerUnknown.value)return;files.value=Array.from((event.target as HTMLInputElement).files||[]);completeDirectories.value=[];emptyDirectories.value=0;selectedPaths.clear();ack.value=false;error.value='';}
function login(){auth.value=true;stop();location.assign('/login?next='+encodeURIComponent(location.pathname+location.search));}
async function request(url:string,init:RequestInit={}){const view=lifecycle,response=await fetch(url,{...init,credentials:'same-origin'});if(!active||view!==lifecycle)throw Error('页面已离开，请到批次记录核对');if(response.status===401){login();throw Error('请重新登录')};if(!response.ok)throw Error(await response.text()||'上传请求失败');return response.json();}
function validBatch(value:any):value is Batch{return value&&/^[a-f0-9]{32}$/.test(value.id)&&validCloudDirectory(value.target)&&Array.isArray(value.items)&&value.items.length+(Array.isArray(value.directories)?value.directories.length:0)<=10000&&value.items.every(validUploadItem)&&(value.directories===undefined||validUploadDirectories(value.directories));}
async function load(id=batch.value?.id||''){
 if(!active||auth.value)return;clearTimeout(timer);const requestID=++generation;controller?.abort();controller=new AbortController();if(!id)historyLoading.value=true;
 try{const response=await fetch(id?'/api/uploads/'+id:'/api/uploads',{credentials:'same-origin',signal:controller.signal});if(requestID!==generation||!active)return;if(response.status===401){if(!id){historyFresh.value=false;historyError.value='请重新登录';historyLoading.value=false;}login();return};if(!response.ok)throw Error(await response.text()||'上传记录不可读');const data=await response.json();if(requestID!==generation||!active)return;
 if(id){if(!validBatch(data)||data.id!==id)throw Error('上传批次响应无效');batch.value=data;target.value=data.target;}else{if(!Array.isArray(data.batches))throw Error('上传历史响应无效');batches.value=data.batches;historyLoaded.value=true;historyFresh.value=true;historyError.value='';historyObserved.value=new Date().toISOString();}error.value='';
 }catch(e:any){if(requestID===generation&&active){error.value=e.message||'上传记录不可读';if(!id){historyFresh.value=false;historyError.value=error.value;}}}finally{if(requestID===generation&&active){if(!id)historyLoading.value=false;if(!auth.value)timer=setTimeout(()=>load(id),2000)}}
}
function receiptVerified(){controlRevision.value++;void load();}
function open(id:string){if(enumerationBusy.value||busy.value||controlBusy.value||enumerationBusy.value||pickerOpen.value||pickerBusy.value)return;invalidateItemControl();batch.value=null;page.value=0;filter.value='';files.value=[];completeDirectories.value=[];selectedPaths.clear();history.pushState(null,'','/uploads?batch='+id);load(id);}
function send(item:Item,file:File,batchID:string,view:number){return new Promise<void>((resolve,reject)=>{
 const transport=new XMLHttpRequest();xhr=transport;const current=()=>active&&view===lifecycle,clear=()=>{if(xhr===transport)xhr=undefined;};
 transport.open('PUT','/api/uploads/'+batchID+'/'+item.id+'/content');transport.withCredentials=true;
 transport.upload.onprogress=event=>{if(current())transferred.value=filename(file)+' · 浏览器 → 本机 '+formatBytes(event.loaded)+' / '+formatBytes(file.size)};
 transport.onload=()=>{clear();if(!current()){reject(Error('上传页面上下文已变化'));return}if(transport.status===401){login();reject(Error('请重新登录'));return}if(transport.status>=200&&transport.status<300)resolve();else reject(Error(transport.responseText||'本机暂存失败'));};
 transport.onerror=()=>{clear();reject(Error('浏览器到本机的传输中断；已接收文件仍会在后台上传，缺失文件需重新选择'));};
 transport.onabort=()=>{clear();reject(Error('浏览器传输已停止'));};transport.send(file);
});}
function canPause(item:Item){return ['queued','hashing','uploading','submitting','finalizing'].includes(item.state);}
function invalidateItemControl(){controlGeneration++;controlController?.abort();controlBusy.value='';controlFeedback.value='';}
async function control(item:Item,action:'pause'|'resume'){
 if(!active||auth.value||!batch.value||controlBusy.value||enumerationBusy.value||pickerOpen.value||pickerBusy.value||pickerUnknown.value||(action==='pause'&&(!canPause(item)||item.pause_requested))||(action==='resume'&&item.state!=='paused'))return;
 const id=batch.value.id,requestID=++controlGeneration;controlBusy.value=item.id;controlFeedback.value='';controlRevision.value++;controlController?.abort();controlController=new AbortController();
 const current=()=>active&&requestID===controlGeneration&&batch.value?.id===id;
 try{const response=await fetch('/api/uploads/'+id+'/'+item.id+'/'+action,{method:'POST',credentials:'same-origin',signal:controlController.signal});if(!current())return;if(response.status===401){login();return;}if(!response.ok)throw Error(await response.text()||'上传控制失败');const result=await response.json();if(!current())return;
  if(!result||result.batch_id!==id||result.item_id!==item.id||Object.keys(result).some(key=>!['batch_id','item_id','state'].includes(key))||!(action==='pause'?['pause_requested','paused'].includes(result.state):result.state==='queued'))throw Error('上传控制回执身份或状态不匹配');
  controlFeedback.value=result.state==='pause_requested'?'暂停请求已保存；已准入请求仍可能完成，等待后续安全点或确认结果，不强制中断。':result.state==='paused'?'此文件已暂停，暂存保留。':'已重新排队；后续将开始新尝试，可能重传分片。';
  await load(id);
 }catch(e:any){if(current())controlFeedback.value='操作未完成或响应未确认：'+(e.message||'请求中断')+'。请刷新批次核对；不会自动重发。';}
 finally{if(requestID===controlGeneration){controlBusy.value='';queueMicrotask(()=>{if(current())(document.querySelector<HTMLElement>('[data-upload-control=\"'+item.id+'\"]')||document.querySelector<HTMLElement>('[data-testid=upload-refresh-batch]'))?.focus();});}}
}
async function start(){
 if(!active||enumerationBusy.value||busy.value||auth.value||enumerationBusy.value||pickerOpen.value||pickerBusy.value||pickerUnknown.value||!ack.value||(!files.value.length&&!completeDirectories.value.length))return;if(!validCloudDirectory(target.value)){error.value='请输入规范绝对网盘目录';return}
 const view=lifecycle,current=()=>active&&view===lifecycle,selectedFiles=files.value.slice(),selectedDirectories=completeDirectories.value.slice(),selectedDirectoryPaths=new Set(selectedDirectories),fixedTarget=target.value;busy.value=true;error.value='';
 try{
  let fixed=batch.value;
  if(!fixed){const manifest=selectedFiles.map(file=>({path:filename(file),size:String(file.size)}));const value=await request('/api/uploads',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({target:fixedTarget,files:manifest,...(selectedDirectories.length?{directories:selectedDirectories}:{})})});if(!current())return;if(!validBatch(value)||value.target!==fixedTarget||value.items?.length!==manifest.length||!value.items.every((item,index)=>item.path===manifest[index].path&&item.size===manifest[index].size))throw Error('上传清单响应与所选文件或目标不一致');if(selectedDirectories.length&&(!value.directories||value.directories.length!==selectedDirectories.length||!value.directories.every(directory=>selectedDirectoryPaths.has(directory.path))))throw Error('上传目录清单响应不匹配，请到批次记录核对，勿重发');fixed=value;batch.value=fixed;history.replaceState(null,'','/uploads?batch='+fixed.id)}
  const selected=new Map(selectedFiles.map(file=>[filename(file),file]));
  for(const item of fixed.items||[]){if(!current())break;if(item.state!=='receiving')continue;const file=selected.get(item.path);if(!file||String(file.size)!==item.size)continue;await send(item,file,fixed.id,view)}
  if(current()){transferred.value=selectedFiles.length?'本机接收已结束，后台上传进度见下方批次。':'目录清单已提交，创建或核对结果见下方批次。';files.value=[];completeDirectories.value=[];selectedPaths.clear();ack.value=false;await load(fixed.id)}
 }catch(e:any){if(current())error.value=e.message||'上传失败'}finally{if(view===lifecycle)busy.value=false}
}
async function retry(){
 if(!active||!batch.value||(!summary.value.failed&&!directoryCounts.value.failed)||enumerationBusy.value||busy.value||controlBusy.value||auth.value||pickerOpen.value||pickerBusy.value||pickerUnknown.value)return;
 invalidateItemControl();controlRevision.value++;busy.value=true;
 const id=batch.value.id,revision=controlGeneration,view=lifecycle,current=()=>active&&view===lifecycle&&revision===controlGeneration&&batch.value?.id===id;
 try{
  const receipt=await request('/api/uploads/'+id,{method:'POST'});if(!current())return;
  if(receipt?.retry_requested!==true)throw Error('重试回执无效');
  controlFeedback.value='服务端已处理重试请求；重新读取批次核对状态，不代表网盘上传完成。';await load(id);
 }catch(e:any){
  if(!current())return;
  // Retry queues files individually; a later rejection does not roll back earlier files.
  controlFeedback.value='重试结果需核对：'+(e.message||'未取得有效回执')+'。部分失败项可能已重新排队；请核对批次刷新结果，不会自动重发。';await load(id);
 }finally{if(view===lifecycle)busy.value=false}
}
async function cancel(){
 stopReview.value=false;
 if(!active||!batch.value||busy.value||controlBusy.value||auth.value||enumerationBusy.value||pickerOpen.value||pickerBusy.value)return;
 invalidateItemControl();controlRevision.value++;busy.value=true;
 const id=batch.value.id,revision=controlGeneration,view=lifecycle,current=()=>active&&view===lifecycle&&revision===controlGeneration&&batch.value?.id===id;
 try{
  const receipt=await request('/api/uploads/'+id,{method:'DELETE'});if(!current())return;
  if(receipt?.cancelled!==true)throw Error('停止回执无效');
  controlFeedback.value='服务端已处理停止和暂存清理请求；在传与结果未知项不因此完成或放行，网盘文件不会被删除。';await load(id);
 }catch(e:any){
  if(!current())return;
  // Cancellation is persisted before staged files are removed; cleanup may fail afterwards.
  controlFeedback.value='停止结果需核对：'+(e.message||'未取得有效回执')+'。文件可能已停止但暂存清理未完成；请核对批次刷新结果，不会自动重发。';await load(id);
 }finally{if(view===lifecycle)busy.value=false}
}
function stop(){historyFresh.value=false;historyLoading.value=false;lifecycle++;stopReview.value=false;invalidateItemControl();if(pickerBusy.value&&!pickerConfirmed.value){pickerUnknown.value=true;directoryResult.value={status:'unknown',message:'离页时新建目录尚未确认，请核对操作记录，勿重发或直接开始上传。',source:target.value,target:''};}pickerOpen.value=false;pickerBusy.value=false;active=false;busy.value=false;generation++;controller?.abort();clearTimeout(timer);xhr?.abort();}
function restore(event:PageTransitionEvent){if(event.persisted&&!auth.value){active=true;load(batch.value?.id||new URLSearchParams(location.search).get('batch')||'')}}
function pop(){
 // popstate arrives after the URL changed; invalidate even when an old write is pending.
 stop();if(auth.value)return;active=true;batch.value=null;page.value=0;filter.value='';files.value=[];completeDirectories.value=[];selectedPaths.clear();ack.value=false;transferred.value='';
 const params=new URLSearchParams(location.search),id=params.get('batch')||'';target.value=params.get('directory')||'/';error.value='';
 if(id&&!/^[a-f0-9]{32}$/.test(id)){error.value='批次ID无效';return}load(id);
}
onMounted(()=>{document.title='上传任务 · CloudHarbor';window.addEventListener('pagehide',stop);window.addEventListener('pageshow',restore);window.addEventListener('popstate',pop);const id=new URLSearchParams(location.search).get('batch')||'';if(id&&!/^[a-f0-9]{32}$/.test(id)){error.value='批次ID无效';return}load(id)});onUnmounted(()=>{stop();window.removeEventListener('pagehide',stop);window.removeEventListener('pageshow',restore);window.removeEventListener('popstate',pop)});
</script>
<template><div class="workspace event-workspace upload-workspace"><WorkspaceSidebar active="/uploads" @error="error=$event"/><main class="main" @keydown.esc="escapePicker"><header class="page-header"><div><p class="eyebrow">本机暂存 → 百度网盘</p><h1>上传任务</h1><p class="muted">批量选择文件或目录，先完整接收到本机，再后台分片上传。关闭页面后，已提交目录和已接收文件继续由后台处理。</p></div><a class="button secondary" href="/cloud/files">返回网盘文件</a></header><details class="upload-secondary-settings"><summary>上传设置与暂存空间</summary><UploadConcurrencySettings :disabled="auth||enumerationBusy||pickerOpen||pickerBusy" @authentication-required="login"/><UploadStorageStatus :selected-bytes="selectedBytes" :disabled="auth||enumerationBusy||pickerOpen||pickerBusy" @authentication-required="login"/></details><p v-if="error" class="notice danger" role="alert">{{error}}</p><section v-if="!batch||batch.items?.some(item=>item.state==='receiving')" class="event-results"><h2>{{batch?'补传此批次缺失文件':'新建上传批次'}}</h2><label>目标网盘目录<input data-testid="upload-target" v-model="target" :disabled="enumerationBusy||pickerOpen||pickerBusy||pickerUnknown||busy||auth||!!batch"/></label><p v-if="batch">本批固定目标：{{batch.target}}</p><button v-if="!batch" type="button" class="button secondary" data-testid="upload-pick-directory" :disabled="busy||auth||pickerBusy||pickerUnknown" @click="togglePicker">{{pickerOpen?'关闭目录选择':'浏览选择网盘目录'}}</button><CloudDirectoryPicker v-if="pickerOpen&&!batch" :initial="target" :disabled="busy||auth||pickerUnknown" @select="picked" @close="closePicker" @busy="directoryBusy" @confirmed="directoryConfirmed" @unknown="directoryUnknown" @authentication-required="login"/><p v-if="pickerBusy" role="status">{{pickerBusyLabel}}；上传批次尚未创建。</p><section v-if="directoryResult" data-testid="upload-directory-result" class="notice" :class="{'danger':directoryResult.status==='unknown'}"><strong>目录操作 · {{directoryResult.status==='confirmed'?'已确认':'结果未知'}}</strong><p>{{directoryResult.message}} {{directoryResult.target}}</p><a :href="directoryResult.operation_id?'/operations?operation_id='+directoryResult.operation_id:'/operations'">查看目录操作记录</a></section><p v-if="pickerUnknown" class="notice danger">目录操作尚待核对，本页暂停创建或补传上传批次；不会自动重发新建或上传。</p><div class="upload-pickers"><label>选择多个文件<input type="file" multiple :disabled="enumerationBusy||pickerOpen||pickerBusy||pickerUnknown||busy||auth" @change="choose"/></label><label>选择目录<input type="file" webkitdirectory multiple :disabled="enumerationBusy||pickerOpen||pickerBusy||pickerUnknown||busy||auth" @change="choose"/></label></div><UploadDirectorySelection v-if="!batch" :disabled="pickerOpen||pickerBusy||pickerUnknown||busy||auth" @selection="completeSelection" @busy="enumerating"/><p v-if="completeDirectories.length" data-testid="upload-selection-preview" class="notice">完整目录：{{completeDirectories[0]}} · {{completeDirectories.length}} 个目录（含 {{emptyDirectories}} 个空目录） · {{files.length}} 个文件 · {{formatBytes(selectedBytes)}}；确认后会创建这些目录。</p><p class="muted">目录上传保留相对层级；上方普通目录选择不会提供空目录；保留空目录请使用完整目录选择。文件会暂存在本机状态目录，需有足够磁盘空间。同名文件由百度另存名称，保留原文件；完成后以实际远端路径为准。</p><p>已选 {{files.length}} 个文件</p><label><input type="checkbox" v-model="ack" :disabled="enumerationBusy||pickerOpen||pickerBusy||pickerUnknown||busy||auth"/>已核对目标，确认将所选文件与目录上传到该网盘目录</label><p><button class="button primary" data-testid="upload-start" :disabled="enumerationBusy||pickerOpen||pickerBusy||pickerUnknown||busy||auth||!ack||(!files.length&&!completeDirectories.length)" @click="start">{{busy?'正在接收…':'接收并开始后台上传'}}</button><a v-if="batch" class="button secondary" href="/uploads">新建其他批次</a></p><p role="status">{{transferred}}</p></section><section v-if="batch" class="event-results"><header class="page-header"><h2>批次详情</h2><button class="button secondary compact" data-testid="upload-refresh-batch" :disabled="!!controlBusy||auth||enumerationBusy||pickerOpen||pickerBusy" @click="load(batch.id)">刷新批次</button><a class="button secondary" href="/uploads">新建上传批次</a><button class="button secondary" data-testid="upload-batch-retry" aria-describedby="upload-retry-policy" :disabled="(!summary.failed&&!directoryCounts.failed)||enumerationBusy||pickerOpen||pickerBusy||pickerUnknown||busy||!!controlBusy||auth" @click="retry">{{batch.directories?.length?'重试明确失败项':'重试明确失败的文件'}}</button><button class="button secondary" :disabled="enumerationBusy||pickerOpen||pickerBusy||busy||!!controlBusy||auth" data-testid="upload-stop-review" @click="reviewStop">{{batch.directories?.length?'停止等待项目':'停止等待或已暂停的文件'}}</button></header><p class="muted">{{batch.id}} · 创建 UTC {{batch.created_at_utc}}</p><p class="muted" id="upload-retry-policy" data-testid="upload-retry-policy">{{directoryCounts.failed?'有明确失败目录可重新排队；未知和已停止目录不重试。':summary.failed?"仅重试明确失败项，需保留本机暂存；重试会开始新尝试，可能重传分片。":"本批没有明确失败的文件，无需重试。"}}<template v-if="summary.unknown"> 本批有 {{summary.unknown}} 项结果未知，后续上传仍等待核对；重试不会放行这些项目。</template></p><UploadDirectoryResults :directories="batch.directories||[]"/><template v-if="batch.items?.length||!batch.directories?.length"><h3 v-if="batch.directories?.length">文件传输（目录单独统计）</h3><div class="upload-batch-summary" data-testid="upload-batch-summary"><div><span>远端已确认</span><strong>{{summary.confirmed}} / {{summary.total}}</strong><small>{{formatBytes(summary.confirmedBytes)}} / {{formatBytes(summary.totalBytes)}}</small></div><div><span>正在处理</span><strong>{{summary.active}}</strong><small>校验、预创建、分片或合并</small></div><div><span>等待处理</span><strong>{{summary.waiting}}</strong><small>已暂停 {{summary.paused}} · 等待本机接收或后台上传</small></div><div><span>需要关注</span><strong>失败 {{summary.failed}} · 待核对 {{summary.unknown}}</strong><small>已停止 {{summary.cancelled}}</small></div></div><p>完成 {{completed}} / {{batch.items?.length}} · 远端提交结果待核对时，本批后续项暂停，不自动重发。</p><p v-if="controlFeedback" class="notice" role="status" data-testid="upload-control-feedback">{{controlFeedback}}</p><UploadTransferStatistics :key="batch.id+'-statistics'" :batch-id="batch.id" :disabled="auth||!!controlBusy" :revision="controlRevision" @authentication-required="login"/><UploadRecoveryHistory :key="batch.id" :batch-id="batch.id" :disabled="auth||!!controlBusy" @authentication-required="login"/><UploadSessionDetails v-if="sessionItem" :key="batch.id+sessionItem" :batch-id="batch.id" :item-id="sessionItem" :disabled="auth||!!controlBusy" @authentication-required="login" @verified="receiptVerified"/><label>状态<select v-model="filter" data-testid="upload-state-filter" @change="page=0"><option value="">全部（{{summary.total}}）</option><option v-for="(label,key) in names" :key="key" :value="key">{{label}}（{{stateCounts[key]}}）</option></select></label><div class="event-table-scroll"><table><thead><tr><th>文件 / 相对路径</th><th>大小</th><th>状态</th><th>阶段进度</th><th>更新 UTC / 结果</th><th>操作</th></tr></thead><tbody><tr v-if="!visible.length"><td colspan="6" class="muted" data-testid="upload-empty-state">{{batch.items?.length?"当前筛选暂无匹配文件。":"本批暂无文件。"}} <button v-if="filter" class="button secondary compact" data-testid="upload-clear-filter" @click="filter='';page=0">显示全部文件</button></td></tr><tr v-for="item in visible" :key="item.id"><td>{{item.path}}</td><td :title="item.size+' B'">{{formatBytes(item.size)}}</td><td>{{names[item.state]}}<small v-if="item.pause_requested" class="cell-sub">暂停请求已保存，等待安全点</small></td><td class="upload-stage" data-testid="upload-stage"><template v-if="uploadItemProgress(item).percent!==null"><progress :value="Number(uploadItemProgress(item).percent)" max="100" :aria-label="item.path+' 阶段进度'"></progress><span>{{uploadItemProgress(item).percent}}%</span></template><small class="cell-sub">{{uploadItemProgress(item).description}}</small><small v-if="['uploading','finalizing','failed','unknown','paused'].includes(item.state)" class="cell-sub">记录的分片确认量：{{formatBytes(item.sent)}}</small></td><td>{{item.updated_at_utc}}<br>{{item.error||item.actual_path}}</td><td><button v-if="canPause(item)" class="button secondary compact" data-testid="upload-item-pause" :data-upload-control="item.id" :disabled="!!controlBusy||auth||enumerationBusy||pickerOpen||pickerBusy||pickerUnknown||item.pause_requested" @click="control(item,'pause')">{{item.pause_requested?'等待暂停':'暂停此文件'}}</button><button v-else-if="item.state==='paused'" class="button secondary compact" data-testid="upload-item-resume" :data-upload-control="item.id" :disabled="!!controlBusy||auth||enumerationBusy||pickerOpen||pickerBusy||pickerUnknown" @click="control(item,'resume')">继续上传</button><span v-else-if="!remoteLocation(item)" class="muted">—</span><a v-if="remoteLocation(item)" class="button secondary compact" data-testid="upload-remote-location" :href="remoteLocation(item)" :title="item.actual_path">查看网盘位置</a><button class="button secondary compact" data-testid="upload-session-toggle" :aria-expanded="sessionItem===item.id" :disabled="auth||!!controlBusy" @click="showSession(item.id)">{{sessionItem===item.id?'收起详情':'会话详情'}}</button></td></tr></tbody></table></div><p data-testid="upload-page-summary">匹配 {{matched}} 项<template v-if="matched"> · 第 {{page+1}} 页</template></p><button class="button secondary" :disabled="page===0" @click="page--">上一页</button><button class="button secondary" :disabled="(page+1)*100>=matched" @click="page++">下一页</button></template><p v-else class="muted">本批仅处理目录，无文件传输。</p></section><section v-else class="event-results" data-testid="upload-history"><h2>最近上传批次（最多50批）</h2><p v-if="historyError" class="notice danger" role="alert">上传历史暂不可读：{{historyError}}<span v-if="historyLoaded">；保留上次读取结果，仅供历史查看。</span><span v-else>；尚未成功读取，不能判断是否存在批次。</span></p><p v-else-if="historyLoaded&amp;&amp;!historyFresh" class="notice">以下是上次读取的历史快照，等待重新核对。</p><div class="event-table-scroll"><table><thead><tr><th>批次</th><th>目标目录</th><th>完成 / 总数</th><th>异常</th><th>创建 UTC</th><th>操作</th></tr></thead><tbody><tr v-for="row in batches" :key="row.id"><td>{{row.id}}</td><td>{{row.target}}</td><td>{{row.completed}} / {{row.total}} 个文件<span v-if="row.directory_summary" class="cell-sub">目录 {{row.directory_summary.confirmed+row.directory_summary.existing}} / {{row.directory_summary.total}} · 待核对 {{row.directory_summary.unknown}} · 失败 {{row.directory_summary.failed}}</span></td><td>失败 {{row.failed}} · 待核对 {{row.unknown}}</td><td>{{row.created_at_utc}}</td><td><button class="button secondary" :disabled="enumerationBusy||busy||pickerBusy||pickerOpen" @click="open(row.id)">查看批次</button></td></tr><tr v-if="!batches.length"><td colspan="6"><span v-if="historyLoading&amp;&amp;!historyLoaded&amp;&amp;!historyError" role="status">正在读取上传批次…</span><span v-else-if="historyError">上传历史暂不可读，未将读取失败视为没有批次。</span><span v-else-if="historyLoaded&amp;&amp;historyFresh" data-testid="upload-history-empty">暂无上传批次。选择文件或目录并核对目标后，可创建第一个上传批次。</span><span v-else>尚无已核对的上传历史，请等待重新读取。</span></td></tr></tbody></table></div><p v-if="historyObserved" class="muted">本机读取 UTC：{{historyObserved}}；来自本地批次记录，不代表重新核对了远端文件。</p></section><UploadBatchStop v-if="stopReview&amp;&amp;batch" :batch-id="batch.id" :target="batch.target" :states="(batch.items||[]).map(item=>item.state)" :directory-states="(batch.directories||[]).map(directory=>directory.state)" @close="stopReview=false" @confirm="cancel"/></main></div></template>
<style scoped>.upload-secondary-settings{margin:10px 0 16px}.upload-secondary-settings>summary{cursor:pointer;border:1px solid #dce3ed;border-radius:8px;background:#fff;padding:9px 12px;width:fit-content;font-weight:600}.upload-workspace input:not([type=checkbox]),.upload-workspace select{border:1px solid #dce2ed;border-radius:6px;padding:8px;max-width:100%}.upload-pickers{display:flex;flex-wrap:wrap;gap:16px;margin:16px 0}.upload-pickers label{display:grid;gap:8px}.upload-workspace :deep(th){width:auto}.upload-workspace td{white-space:normal;overflow-wrap:anywhere;max-width:400px}</style>
